   562	
   563	\begin{lemma}[Monotonicity of the robustness bound in its universal constants]\label{lem:delta-qld-mono-support}
   564		\lean{MIPStarRE.QPBT.deltaQld_mono}
   565		\leanok
   566		\uses{thm:pauli}
   567		Write $\delta_{\mathrm{qld}}^{a,b}(\eps,m,d,q) = a(md)^a\bigl(\eps^b + q^{-b} + 2^{-bmd}\bigr)$ for the soundness function of Theorem~\ref{thm:pauli} with universal constants $a$ and $b$. Let $(q,m,d)$ be an admissible parameter tuple (Definition~\ref{def:admissible}), let $1 \le a \le a'$, let $0 < b' \le b$, and let $0 \le \eps \le 1$. Then
   568		\[
   569			\delta_{\mathrm{qld}}^{a,b}(\eps,m,d,q) \le \delta_{\mathrm{qld}}^{a',b'}(\eps,m,d,q)\;.
   570		\]
   571	\end{lemma}
   572	\begin{proof}
   573		\leanok
   574		\uses{def:admissible}
   575		Admissibility gives $md \ge 1$ and $q \ge 1$, so $a(md)^a \le a'(md)^{a'}$. In the bracket, $\eps^b \le \eps^{b'}$ because $0 \le \eps \le 1$ and $0 < b' \le b$; $q^{-b} \le q^{-b'}$ because $q \ge 1$ and $-b \le -b'$; and $2^{-bmd} \le 2^{-b'md}$ because $md \ge 0$ and $-bmd \le -b'md$. Both factors are nonnegative, so the two products compare factorwise.
   576	\end{proof}

